(()=>{const style=document.createElement('style');style.textContent='.tn-help-v2,.svc-manager{cursor:pointer}.tn-help-v2:focus-visible,.svc-manager:focus-visible{outline:3px solid #b75e35;outline-offset:4px}.svc-director-cta{font-weight:600;color:#995132}';document.head.append(style);function mount(){const zh=location.pathname.startsWith('/zh/');document.querySelectorAll('.tn-help-v2,.svc-manager').forEach(card=>{if(card.dataset.directorContact)return;card.dataset.directorContact='1';const role=card.querySelector('.th-since');if(role)role.textContent=zh?'工厂总监 · 您的项目对接人':'Factory Director · Your project contact';const head=card.querySelector('.th-kick');if(head)head.textContent=zh?'苏先生':'Mr Su';const img=card.querySelector('img');if(img)img.alt=zh?'苏先生，EVERCUP工厂总监':'Mr Su, EVERCUP Factory Director';card.setAttribute('role','link');card.tabIndex=0;card.setAttribute('aria-label',zh?'向苏先生工厂总监提交询盘':'Enquire with Mr Su, Factory Director');const cta=card.querySelector('.th-cta');if(cta)cta.textContent=zh?'向工厂总监询盘 →':'Enquire with the factory director →';function go(){if(/\/contact\/?$/.test(location.pathname)){const input=document.querySelector('.buyer-rfq-form input');input?.scrollIntoView({behavior:'smooth',block:'center'});input?.focus({preventScroll:true});return}location.href=(zh?'/zh':'')+'/contact/?contact=Mr-Su-Factory-Director'}card.addEventListener('click',e=>{if(e.target.closest('a,button,input,textarea,select'))return;go()});card.addEventListener('keydown',e=>{if(e.target===card&&e.key==='Enter'){e.preventDefault();go()}})})}let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;mount()})}).observe(document.body,{childList:true,subtree:true});mount()})();

